from pathlib import Path
import datetime,hashlib,json,re
base=Path('/workspace/scratch/all-target-curvature-residual-construct')
packet=Path('/workspace/Math-curvature-20261026/frontiers/source_derivative_gaussian_20261025')
source=packet/'SourceAllTargetCurvatureResidual.lean'
now=datetime.datetime.now(datetime.timezone.utc).isoformat()
def ident(p):
    return {'path':str(p),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
def write(name,value): (base/name).write_text(json.dumps(value,indent=2)+'\n')
freeze=json.loads((base/'FROZEN_SOURCE.json').read_text())
assert ident(source)==freeze['source']
obj=base/'build/SourceAllTargetCurvatureResidual.olean'
assert ident(obj)==freeze['object']
receipts=[json.loads(p.read_text()) for p in sorted((base/'runs').glob('*/receipt.json'))]
expected={'strict-001':1,'strict-002':0,'kernel-001':0,'inventory-001':1,'inventory-002':0,'controls-001':1,'controls-002':0,'false-growth-001':1}
assert {x['label']:x['exit_code'] for x in receipts}==expected
kernels=[x for x in receipts if x['label'].startswith('kernel-')]
assert len(kernels)==1
assert freeze['frozen_utc']<kernels[0]['started_utc']
inv=(base/'runs/inventory-002/output.log').read_text()
constants=re.findall(r'^INVENTORY\|(\w+)\|([^\n]+)',inv,re.M)
axs=dict(re.findall(r'^AXIOMS\|([^|\n]+)\|\[([^\]]*)\]',inv,re.M))
assert len(constants)==12 and len(axs)==12
lines=source.read_text().splitlines()
exports={}
for i,line in enumerate(lines,1):
    m=re.match(r'(theorem|def) ([A-Za-z0-9_]+)',line)
    if m: exports['I4SourceAllTargetCurvatureResidual.'+m[2]]={'kind':m[1],'line':i}
assert len(exports)==11
rows=[]
for kind,name in constants:
    actual_axioms=[a.strip() for a in axs[name].replace('\n','').split(',')]
    assert set(actual_axioms)=={'propext','Classical.choice','Quot.sound'}
    public=name in exports
    assert public or name=='I4SourceAllTargetCurvatureResidual.allTargetCurvatureResidualRadius.congr_simp'
    rows.append({'name':name,'lean_kind':kind,'classification':'public_export' if public else 'compiler_generated_congruence_theorem','source_line':exports.get(name,{}).get('line'),'axioms':actual_axioms})
write('TARGET_CLASSIFICATION.json',{'module':'SourceAllTargetCurvatureResidual','inventory_method':'Lean environment actual module index, every env constant whose getModuleIdxFor? equals target index','source':ident(source),'receipt':ident(base/'runs/inventory-002/receipt.json'),'constants':rows,'actual_module_constant_count':12,'declared_public_export_count':11,'public_theorem_count':10,'public_definition_count':1,'generated_theorem_count':1,'omitted_constants':[],'all_axioms_standard_three':True})
write('INVENTORY.json',{'module':'SourceAllTargetCurvatureResidual','actual_module_constants':[name for _,name in constants],'public_targets':list(exports),'axiom_report':ident(base/'runs/inventory-002/output.log'),'classification':ident(base/'TARGET_CLASSIFICATION.json')})
write('EXECUTION_RECORD_INDEX.json',{'created_utc':now,'scope':'new leaf and its scratch controls only; old completed applicable verification reused','runs':[{'label':r['label'],'command':r['command'],'exit_code':r['exit_code'],'started_utc':r['started_utc'],'ended_utc':r['ended_utc'],'elapsed_seconds':r['elapsed_seconds'],'receipt':ident(base/'runs'/r['label']/'receipt.json'),'raw_log':ident(base/'runs'/r['label']/'output.log'),'before':r['before'],'after':r['after']} for r in receipts],'exactly_one_own_module_kernel':len(kernels),'old_checks_or_reviews_replayed':False,'failures_preserved':['strict-001: missing I4SourceContact namespace open; corrected only new source before freeze','inventory-001: helper output compilation lacked -R scratch root; fixed invocation only','controls-001: two strict lint failures and (1+3)^n vs 4^n normalization; corrected only scratch control source'],'intended_negative':'false-growth-001: arithmetic target-growth-factor erasure rejected with sole False'})
