write('SOURCE_OBJECT_IDENTITIES.json',{'final_source':ident(source),'frozen_source_record':ident(base/'FROZEN_SOURCE.json'),'own_module_olean':ident(obj),'own_module_ilean':ident(obj.with_suffix('.ilean')),'scratch_helper_objects':[ident(p) for p in sorted((base/'build').glob('*.olean')) if p!=obj],'production_cache_installation':'NOT PERFORMED; root owns installation','old_source_hashes_or_old_verification_recomputed':False,'precode_commit':'5141e92c22edc6a62d307e59f52dbfb2bdb1aba8','reused_qualified_baseline':'19f7baf: 38 modules, 989 targets, 32 inputs','strict_receipt':ident(base/'runs/strict-002/receipt.json'),'sole_kernel_receipt':ident(base/'runs/kernel-001/receipt.json')})
